#pragma once

// Component reflection metadata: shared by the serialization code in World.h and the
// editor UI. The TYPES and the GENERATOR live here (hand-written, stable). The DATA
// (the InitKnownComponents() body) lives in the autogenerated ComponentMetaData.h, which is
// produced by GenerateComponentMetaData() reading EVERY header of the engine source folder.
// Keep these two files distinct.
//
// A component is any "struct X : ComponentBase<X>" declared inside namespace Components, in ANY
// header of SeeD\src -- put a component next to the system that owns it. The generated table is
// included ONCE, from Main.cpp after the last engine header, because it needs every component to
// already be declared (offsetof/sizeof/mask); InitKnownComponents() is forward-declared below so
// World.h and Editor.h can call it long before that point.
//
// This header is included from World.h (right before UIHelpers.h) so it only needs
// Components::Mask and String to be defined.

#include <fstream>
#include <vector>
#include <format>
#include <string>
#include <filesystem>
#include <algorithm>

enum class PropertyTypes : int
{
    _none,
    _int,
    _uint,
    _float,
    _float2,
    _float3,
    _float4,
    _quaternion,
    _float4x4,
    _assetID,
    _Handle,
    _bool,
    _raw    // any type the generator doesn't otherwise recognize (e.g. char, enums, BitFlags<>)
};
bool KnownType(String typeName)
{
    if (typeName == "int")
        return true;
    else if (typeName == "uint")
        return true;
    else if (typeName == "float")
        return true;
    else if (typeName == "float2")
        return true;
    else if (typeName == "float3")
        return true;
    else if (typeName == "float4")
        return true;
    else if (typeName == "quaternion")
        return true;
    else if (typeName == "float4x4")
        return true;
    else if (typeName == "assetID")
        return true;
    else if (typeName == "bool")
        return true;
    return false;
}
struct MemberInfoParse
{
    String name;
    String dataType;
    String dataTemplateType;
    String dataCount;
};
struct ComponentInfoParse
{
    String name;
    std::vector<MemberInfoParse> members;
    String propertyDrawPtr;
    String sourceFile;  // header it was found in, for the generated banner + diagnostics
};
struct MemberInfo
{
    String name;
    PropertyTypes dataType;
    Components::Mask dataTemplateType;
    int dataCount;
    int offset;
    int size;   // exact byte span of the member (the WHOLE array for array members)
};
struct ComponentInfo
{
    String name;       // Component name
    Components::Mask mask;
    void (*PropertyDraw)(char*);
    uint align;        // alignof the component struct, to tell real tail padding from a missing field
    std::vector<MemberInfo> members;
};
std::vector<ComponentInfo> knownComponents;

// Autogenerated in ComponentMetaData.h, which Main.cpp includes after the last engine header (it
// needs every component declared). Forward-declared so the callers that come before it compile.
void InitKnownComponents();

// Draws every reflected member of a component via the metadata above -- the same rendering the
// property window falls back to when a component has no custom PropertyDraw. Defined in UI.h
// (needs AssetLibrary/fileBrowserWindow); forward-declared here so a custom PropertyDraw (e.g.
// Instance's, in World.h) can call it to get the default rendering alongside its own controls.
void DefaultPropertyDraw(Components::Mask mask, char* data);

// ============================================================================
// Generator
// ============================================================================

static bool MetaIsIdentChar(char c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'; }
static String MetaTrim(const String& s)
{
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == String::npos)
        return String("");
    size_t b = s.find_last_not_of(" \t\r\n");
    return String(s.substr(a, b - a + 1));
}
// Leading identifier of a trimmed line ("static", "enum", "float4"...), empty if it starts with punctuation.
static String MetaFirstToken(const String& s)
{
    size_t i = 0;
    while (i < s.size() && MetaIsIdentChar(s[i])) i++;
    return String(s.substr(0, i));
}
static bool MetaStartsWith(const String& s, const char* prefix)
{
    return s.rfind(prefix, 0) == 0;
}
// Blanks out comments and string/char literal CONTENTS in one line. blockComment carries the
// /* */ state across lines. Doing literals in the same pass matters twice: a "//" inside a string
// must not start a comment, and a brace inside a literal must not move the struct brace depth.
static String MetaClean(const String& line, bool& blockComment)
{
    String out;
    for (size_t i = 0; i < line.size(); i++)
    {
        char c = line[i];
        char next = (i + 1 < line.size()) ? line[i + 1] : '\0';
        if (blockComment)
        {
            if (c == '*' && next == '/') { blockComment = false; i++; }
            continue;
        }
        if (c == '/' && next == '/')
            break;
        if (c == '/' && next == '*') { blockComment = true; i++; continue; }
        if (c == '"' || c == '\'')
        {
            char quote = c;
            out += quote;
            i++;
            while (i < line.size() && line[i] != quote)
            {
                if (line[i] == '\\') i++;   // skip the escaped char, quote included
                i++;
            }
            out += quote;                   // literal content dropped, delimiters kept
            continue;
        }
        out += c;
    }
    return out;
}
// "namespace Components" / "namespace Components {" -> "Components". Empty when the line opens no namespace.
static String MetaNamespaceOpened(const String& line)
{
    String t = MetaTrim(line);
    if (MetaFirstToken(t) != "namespace")
        return String("");
    String rest = MetaTrim(String(t.substr(9)));
    return MetaFirstToken(rest);
}
// "struct Foo : ComponentBase<Foo>[, Bar]" -> "Foo". Empty when the line declares no component.
static String MetaComponentDeclared(const String& line)
{
    String t = MetaTrim(line);
    if (MetaFirstToken(t) != "struct")
        return String("");
    if (t.find("ComponentBase<") == String::npos)
        return String("");
    String rest = MetaTrim(String(t.substr(6)));
    return MetaFirstToken(rest);
}
// "static void TerrainPropertyDraw(char* p)" -> "Terrain". Empty for anything else, so a call site
// or an unrelated function can't be mistaken for a component's custom drawer.
static String MetaPropertyDrawTarget(const String& line)
{
    String t = MetaTrim(line);
    if (MetaFirstToken(t) == "static")
        t = MetaTrim(String(t.substr(6)));
    if (MetaFirstToken(t) != "void")
        return String("");
    size_t paren = t.find("(");
    if (paren == String::npos)
        return String("");
    if (t.find("char*", paren) == String::npos && t.find("char *", paren) == String::npos)
        return String("");

    String funcName = MetaTrim(String(t.substr(4, paren - 4)));
    const String suffix = "PropertyDraw";
    if (funcName.size() <= suffix.size() || funcName.compare(funcName.size() - suffix.size(), suffix.size(), suffix) != 0)
        return String("");
    return String(funcName.substr(0, funcName.size() - suffix.size()));
}

enum class MetaFieldParse
{
    field,        // a data member the metadata describes
    ignored,      // legitimately carries no instance data (blank, #define, method, static member, nested type header)
    unsupported   // IS a data member, but one the metadata cannot describe -> logged, never silently dropped
};
static MetaFieldParse MetaParseField(const String& line, MemberInfoParse& out, String& reason)
{
    String t = MetaTrim(line);
    if (t.empty() || t[0] == '#' || t[0] == '{' || t[0] == '}')
        return MetaFieldParse::ignored;     // blank, preprocessor, or a brace line

    String first = MetaFirstToken(t);
    // Nested type headers, access specifiers, and members that are not part of the object layout.
    if (first == "enum" || first == "struct" || first == "union" || first == "class" ||
        first == "static" || first == "inline" || first == "constexpr" || first == "template" ||
        first == "typedef" || first == "using" || first == "friend" || first == "return" ||
        first == "virtual" || first == "explicit" || first == "operator" ||
        first == "public" || first == "private" || first == "protected")
        return MetaFieldParse::ignored;

    size_t semi = t.find(";");
    if (semi == String::npos)
        return MetaFieldParse::ignored;     // brace lines, continuations, nested bodies

    String decl = String(t.substr(0, semi));
    size_t eq = decl.find("=");             // drop the default initializer, keep the declaration
    if (eq != String::npos)
        decl = String(decl.substr(0, eq));
    if (decl.find("(") != String::npos)
        return MetaFieldParse::ignored;     // method / constructor / function pointer member
    decl = MetaTrim(decl);
    if (decl.empty())
        return MetaFieldParse::ignored;

    // "name[count]" -> dataCount, and the count expression is emitted verbatim (it is usually a
    // #define or an HLSL:: constant, which the generated file can see just as well as we can).
    String count = "1";
    if (decl[decl.size() - 1] == ']')
    {
        size_t open = decl.rfind("[");
        if (open == String::npos)
        {
            reason = "unbalanced []";
            return MetaFieldParse::unsupported;
        }
        count = MetaTrim(String(decl.substr(open + 1, decl.size() - open - 2)));
        decl = MetaTrim(String(decl.substr(0, open)));
    }

    if (decl.find(",") != String::npos)
    {
        reason = "multiple declarators on one line";
        return MetaFieldParse::unsupported;
    }
    if (decl.find("*") != String::npos || decl.find("&") != String::npos)
    {
        reason = "pointer or reference member";
        return MetaFieldParse::unsupported;
    }
    // A ':' left in the declaration (outside "::" and outside template arguments) is a bitfield.
    for (size_t i = 0, chevrons = 0; i < decl.size(); i++)
    {
        if (decl[i] == '<') chevrons++;
        else if (decl[i] == '>' && chevrons > 0) chevrons--;
        else if (decl[i] == ':' && chevrons == 0)
        {
            if (i + 1 < decl.size() && decl[i + 1] == ':') { i++; continue; }
            if (i > 0 && decl[i - 1] == ':') continue;
            reason = "bitfield member";
            return MetaFieldParse::unsupported;
        }
    }

    // The member name is the last identifier of the declaration; everything before it is the type
    // (so "unsigned int x", "HLSL::LightType type" and "Handle<Mesh> m" all split correctly).
    size_t end = decl.size();
    size_t start = end;
    while (start > 0 && MetaIsIdentChar(decl[start - 1])) start--;
    String type = MetaTrim(String(decl.substr(0, start)));
    out.name = String(decl.substr(start, end - start));
    out.dataCount = count;
    if (out.name.empty() || type.empty())
    {
        reason = "unrecognized declaration";
        return MetaFieldParse::unsupported;
    }

    // Type qualifiers the layout doesn't care about.
    while (true)
    {
        String q = MetaFirstToken(type);
        if (q != "const" && q != "volatile" && q != "mutable") break;
        type = MetaTrim(String(type.substr(q.size())));
    }

    // Only Handle<T> carries a component mask. Any other template (BitFlags<Flags>, ...) is raw
    // data -- emitting Components::<arg>::mask for those would not even compile.
    String templateArg;
    size_t chevron = type.find("<");
    if (chevron != String::npos)
    {
        size_t closing = type.rfind(">");
        if (closing == String::npos || closing < chevron)
        {
            reason = "unbalanced <>";
            return MetaFieldParse::unsupported;
        }
        templateArg = MetaTrim(String(type.substr(chevron + 1, closing - chevron - 1)));
        type = MetaTrim(String(type.substr(0, chevron)));
    }
    if (MetaStartsWith(type, "Components::"))
        type = String(type.substr(12));
    if (MetaStartsWith(templateArg, "Components::"))
        templateArg = String(templateArg.substr(12));

    if (type == "Handle" && !templateArg.empty())
    {
        out.dataType = "Handle";
        out.dataTemplateType = std::format("Components::{0}::mask", templateArg.c_str());
    }
    else
    {
        // Unknown types are kept as _raw so the field list always covers the whole struct
        // (and no handle is ever silently dropped).
        out.dataType = KnownType(type) ? type : String("raw");
        out.dataTemplateType = "NULL";
    }
    return MetaFieldParse::field;
}

// A "<Name>PropertyDraw(char*)" seen somewhere in namespace Components. Resolved against the
// components in a second pass, so a drawer may sit in a header parsed before its component's.
struct PropertyDrawParse
{
    String component;
    String sourceFile;
};

// Parses one header, appending every component it declares and every custom drawer it defines.
// Returns the number of components found.
uint ParseHeaderComponents(String path, std::vector<ComponentInfoParse>& cmpInfos, std::vector<PropertyDrawParse>& drawers)
{
    std::ifstream fin((std::string)path);
    if (!fin.is_open())
    {
        IOs::Log("Component metadata: cannot open {}", path.c_str());
        return 0;
    }

    String fileName = String(std::filesystem::path((std::string)path).filename().string());
    uint found = 0;
    bool blockComment = false;
    String currentNamespace;
    String rawLine;
    while (getline(fin, rawLine))
    {
        String line = MetaClean(rawLine, blockComment);

        String ns = MetaNamespaceOpened(line);
        if (!ns.empty())
            currentNamespace = ns;

        String cmpName = MetaComponentDeclared(line);
        if (!cmpName.empty())
        {
            // ComponentBase, Handle and the Mask live in namespace Components, and the generated
            // table qualifies every name with it -- a component declared anywhere else would not
            // compile, so say so instead of emitting it.
            if (currentNamespace != "Components")
            {
                IOs::Log("Component metadata: {} ({}) is not declared inside namespace Components -- skipped", cmpName.c_str(), fileName.c_str());
                continue;
            }
            bool duplicate = false;
            for (uint i = 0; i < (uint)cmpInfos.size(); i++)
                if (cmpInfos[i].name == cmpName) duplicate = true;
            if (duplicate)
            {
                IOs::Log("Component metadata: {} ({}) is declared twice -- second one skipped", cmpName.c_str(), fileName.c_str());
                continue;
            }

            cmpInfos.resize(cmpInfos.size() + 1);
            ComponentInfoParse& cmpInfo = cmpInfos[cmpInfos.size() - 1];
            cmpInfo.propertyDrawPtr = "nullptr";
            cmpInfo.name = cmpName;
            cmpInfo.sourceFile = fileName;
            found++;

            // Walk the struct body by brace depth, collecting fields at depth 1 only: a nested
            // enum/struct/union body sits at depth 2 and is skipped WITHOUT ending the scan (its
            // closing "};" used to be mistaken for the component's own, truncating the field list).
            uint depth = 0;
            bool entered = false;
            uint guard = 0;
            while (true)
            {
                uint depthBefore = depth;
                for (uint i = 0; i < (uint)line.size(); i++)
                {
                    if (line[i] == '{') depth++;
                    else if (line[i] == '}' && depth > 0) depth--;
                }
                if (depth > 0) entered = true;

                if (depthBefore == 1)
                {
                    MemberInfoParse info;
                    String reason;
                    MetaFieldParse res = MetaParseField(line, info, reason);
                    if (res == MetaFieldParse::field)
                        cmpInfo.members.push_back(info);
                    else if (res == MetaFieldParse::unsupported)
                        IOs::Log("Component metadata: {}.{} ({}) skipped -- {}", cmpName.c_str(), MetaTrim(line).c_str(), fileName.c_str(), reason.c_str());
                }

                if (entered && depth == 0)
                    break;
                if (++guard > 1000)
                {
                    IOs::Log("Component metadata: unbalanced braces while parsing {} ({}) -- field list truncated", cmpName.c_str(), fileName.c_str());
                    break;
                }
                if (!getline(fin, rawLine))
                    break;
                line = MetaClean(rawLine, blockComment);
            }
        }
        else if (currentNamespace == "Components")
        {
            String drawTarget = MetaPropertyDrawTarget(line);
            // DefaultPropertyDraw is the metadata-driven fallback renderer, not a component's.
            if (drawTarget.empty() || drawTarget == "Default")
                continue;
            // The same drawer legitimately appears twice (declaration in World.h, definition in
            // Loading.h / Editor.h); resolving is idempotent, so both entries are harmless.
            drawers.push_back({ drawTarget, fileName });
        }
    }

    fin.close();
    return found;
}

String FormatMetaData(ComponentInfoParse& cmpInfo)
{
    String out = std::format("// {0}\nknownComponents.push_back(\n \t{{ \"{1}\", Components::{1}::mask, {2}, alignof(Components::{1}), \n \t\t{{\n",
        cmpInfo.sourceFile.c_str(), cmpInfo.name.c_str(), cmpInfo.propertyDrawPtr.c_str());

    for (uint i = 0; i < cmpInfo.members.size(); i++)
    {
        auto& m = cmpInfo.members[i];
        out += std::format("\t\t\t{{ \"{0}\", PropertyTypes::_{1}, {2}, {3}, offsetof(Components::{4}, {0}), sizeof(Components::{4}::{0}) }},\n",
            m.name.c_str(), m.dataType.c_str(), m.dataTemplateType.c_str(), m.dataCount.c_str(), cmpInfo.name.c_str());
    }

    out += "\t\t}\n \t}";
    out += "); \n";

    return out;
}

// The engine source folder. __FILE__ is this header's absolute path at build time, so the
// generator finds the sources it was built from with no hardcoded machine path; the working
// directory (the app runs with cwd = SeeD\) is the fallback. Empty when neither works.
String SourceCodeDir()
{
    namespace fs = std::filesystem;
    std::error_code ec;

    fs::path fromFile = fs::path(__FILE__).parent_path();
    if (fs::exists(fromFile / "World.h", ec))
        return String(fromFile.string() + "\\");

    fs::path fromCwd = fs::current_path(ec) / "src";
    if (fs::exists(fromCwd / "World.h", ec))
        return String(fromCwd.string() + "\\");

    return String("");
}

// Regenerates ComponentMetaData.h from EVERY header of the engine source folder (Shaders\ is a
// subfolder, so the non-recursive walk leaves it alone). Called from the editor's
// "Generate components Metadata" menu; the result only takes effect after a rebuild.
void GenerateComponentMetaData()
{
    namespace fs = std::filesystem;

    String dir = SourceCodeDir();
    if (dir.empty())
    {
        IOs::Log("Component metadata: engine source folder not found (looked next to ComponentMetaTypes.h and in .\\src)");
        return;
    }

    std::error_code ec;
    std::vector<String> files;
    for (auto& entry : fs::directory_iterator((std::string)dir, ec))
    {
        if (!entry.is_regular_file() || entry.path().extension() != ".h")
            continue;
        String fileName = String(entry.path().filename().string());
        if (fileName == "ComponentMetaData.h")  // our own output
            continue;
        files.push_back(fileName);
    }
    // Deterministic order, and World.h first so the core components keep their table positions
    // (the order feeds SchemaGUID() and the editor's component combos).
    std::sort(files.begin(), files.end());
    auto world = std::find(files.begin(), files.end(), String("World.h"));
    if (world != files.end())
        std::rotate(files.begin(), world, world + 1);

    std::vector<ComponentInfoParse> cmpInfos;
    std::vector<PropertyDrawParse> drawers;
    for (uint i = 0; i < (uint)files.size(); i++)
        ParseHeaderComponents(dir + files[i], cmpInfos, drawers);

    // Drawers resolve only once every header has been read, so their file may come before their
    // component's. An unmatched one is almost always a typo in the "<Component>PropertyDraw" name.
    for (uint d = 0; d < (uint)drawers.size(); d++)
    {
        bool matched = false;
        for (uint i = 0; i < (uint)cmpInfos.size(); i++)
            if (cmpInfos[i].name == drawers[d].component)
            {
                cmpInfos[i].propertyDrawPtr = "Components::" + drawers[d].component + "PropertyDraw";
                matched = true;
            }
        if (!matched)
            IOs::Log("Component metadata: {}PropertyDraw ({}) matches no component", drawers[d].component.c_str(), drawers[d].sourceFile.c_str());
    }

    String outPath = dir + "ComponentMetaData.h";
    std::ofstream fout((std::string)outPath);
    if (!fout.is_open())
    {
        IOs::Log("Component metadata: cannot write {}", outPath.c_str());
        return;
    }

    fout << "#pragma once" << std::endl;
    fout << "// Generated by GenerateComponentMetaData() (ComponentMetaTypes.h) -- DO NOT EDIT." << std::endl;
    fout << std::format("// {} components, from {} headers of SeeD\\src.", (uint)cmpInfos.size(), (uint)files.size()) << std::endl;
    fout << "// Included once from Main.cpp, after the last engine header." << std::endl;

    fout << "void InitKnownComponents() { \n" << std::endl;
    fout << "static bool initialized = false;\n" << std::endl;
    fout << "if(initialized) return;\n" << std::endl;
    fout << "initialized = true;\n" << std::endl;

    for (uint i = 0; i < (uint)cmpInfos.size(); i++)
        fout << FormatMetaData(cmpInfos[i]);

    fout << "}\n" << std::endl;

    fout.close();
    IOs::Log("Component metadata: {} components from {} headers -> {}", (uint)cmpInfos.size(), (uint)files.size(), outPath.c_str());
}

// Sanity tripwire for the generated table: every component that registered a bucket must have an
// entry, every entry must sit on the right bucket, and every struct must be fully covered by its
// members. Anything caught here means a STALE ComponentMetaData.h -- regenerate it via the
// "Generate components Metadata" menu and rebuild. Call after InitKnownComponents().
void VerifyKnownComponents()
{
    // A component declared in a header the generator never saw is invisible in the editor AND
    // silently dropped on save, so compare against what actually registered at static init.
    if ((uint)knownComponents.size() != Components::masksIndex)
    {
        IOs::Log("Metadata error: {} components registered at runtime but {} in the metadata table -- regenerate ComponentMetaData.h",
            Components::masksIndex, (uint)knownComponents.size());
        seedAssert(false);
    }

    bool bucketSeen[Components::componentMaxCount] = {};
    for (uint i = 0; i < knownComponents.size(); i++)
    {
        auto& cmp = knownComponents[i];
        uint bucket = Components::MaskToBucket(cmp.mask);
        uint stride = Components::strides[bucket];

        if (bucket >= Components::masksIndex || bucketSeen[bucket])
        {
            IOs::Log("Metadata error: {} maps to bucket {}, which is out of range or already taken -- regenerate ComponentMetaData.h",
                cmp.name.c_str(), bucket);
            seedAssert(false);
        }
        bucketSeen[bucket] = true;
        // names[] comes from typeid at registration: a mismatch means the table names a component
        // that no longer exists under that name.
        if (Components::names[bucket] != cmp.name)
        {
            IOs::Log("Metadata error: table says '{}' for bucket {} but the registered component is '{}' -- regenerate ComponentMetaData.h",
                cmp.name.c_str(), bucket, Components::names[bucket].c_str());
            seedAssert(false);
        }

        for (uint m = 0; m < cmp.members.size(); m++)
        {
            if ((uint)cmp.members[m].offset + (uint)cmp.members[m].size > stride)
            {
                IOs::Log("Metadata error: {}.{} ends at {} but the stride is {}",
                    cmp.name.c_str(), cmp.members[m].name.c_str(), cmp.members[m].offset + cmp.members[m].size, stride);
                seedAssert(false);
            }
            // Members must be in strictly ascending offset order: SaveEntities writes the schema
            // fields in this order and the by-name migration relies on it.
            if (m > 0 && cmp.members[m].offset <= cmp.members[m - 1].offset)
            {
                IOs::Log("Metadata error: {} members out of offset order ('{}' offset {} <= '{}' offset {}) -- regenerate ComponentMetaData.h",
                    cmp.name.c_str(), cmp.members[m].name.c_str(), cmp.members[m].offset,
                    cmp.members[m - 1].name.c_str(), cmp.members[m - 1].offset);
                seedAssert(false);
            }
        }

        // What is left after the last member can only be real tail padding, which is always
        // smaller than the struct's alignment. More than that means a field is missing from the
        // table -- the exact failure that used to hide behind "size = next member's offset".
        // (Entity has no reflected member on purpose: it is the entity id itself.)
        if (!cmp.members.empty())
        {
            auto& last = cmp.members[cmp.members.size() - 1];
            uint end = (uint)last.offset + (uint)last.size;
            if (stride > end && stride - end >= cmp.align)
            {
                IOs::Log("Metadata error: {} covers {} of {} bytes (align {}) -- a field is missing, regenerate ComponentMetaData.h",
                    cmp.name.c_str(), end, stride, cmp.align);
                seedAssert(false);
            }
        }
    }
}

// Stable 64-bit fingerprint of the whole component schema: every component's name + stride
// and every member's name/type/count/offset, in knownComponents order. Saved into .seed files
// (v4+) so Load can tell whether a file was written by a build with the EXACT same layout. A
// match -> the file is byte-identical to us, Load skips all schema verification + migration and
// bulk-copies. A mismatch (rename, reorder, new/removed field, type/size change) flips the
// fingerprint -> Load falls back to the by-name migration path. FNV-1a. First call MUST be after
// InitKnownComponents(); the result is then cached for the rest of the run (the schema is fixed
// once loaded -- regenerating metadata only takes effect after a rebuild).
uint64_t SchemaGUID()
{
    static bool cached = false;
    static uint64_t guid = 0;
    if (cached) return guid;

    uint64_t h = 1469598103934665603ull; // FNV offset basis
    auto mix = [&](const void* p, size_t n)
    {
        const unsigned char* b = (const unsigned char*)p;
        for (size_t i = 0; i < n; i++) h = (h ^ b[i]) * 1099511628211ull; // FNV prime
    };
    auto mixU32 = [&](uint32_t v) { mix(&v, sizeof(v)); };
    auto mixStr = [&](const std::string& s) { mixU32((uint32_t)s.size()); mix(s.data(), s.size()); };
    for (auto& kc : knownComponents)
    {
        mixStr((std::string)kc.name);
        mixU32(Components::strides[Components::MaskToBucket(kc.mask)]);
        mixU32((uint32_t)kc.members.size());
        for (auto& m : kc.members)
        {
            mixStr((std::string)m.name);
            mixU32((uint32_t)m.dataType);
            mixU32((uint32_t)m.dataCount);
            mixU32((uint32_t)m.offset);
        }
    }
    guid = h;
    cached = true;
    return guid;
}
